import Foundation
import XCTest
@testable import PhiKit
@testable import PhiTerminal

/// M1 parity gate: the same raw ANSI bytes, decoded by the Swift adapter and by
/// the Go oracle, must agree in geometry, cursor and every cell, not only text
/// (§9.2). Fixtures are reviewed constants, never regenerated by the oracle.
final class ANSIReplayParityTests: XCTestCase {
  struct Fixture {
    let name: String
    let cols: UInt16
    let rows: UInt16
    let bytes: [UInt8]
  }

  static let fixtures: [Fixture] = [
    Fixture(name: "ascii", cols: 80, rows: 24, bytes: Array("alpha\r\nbeta".utf8)),
    Fixture(name: "sgr-basic", cols: 80, rows: 24, bytes: Array("\u{1B}[1mbold\u{1B}[0m \u{1B}[31mred\u{1B}[0m".utf8)),
    Fixture(
      name: "sgr-indexed-rgb", cols: 80, rows: 24,
      bytes: Array("\u{1B}[38;5;196mx\u{1B}[48;2;10;20;30my\u{1B}[4mz\u{1B}[0m".utf8)),
    Fixture(
      name: "wrap-100-w", cols: 80, rows: 24,
      bytes: Array(String(repeating: "W", count: 100).utf8)),
    Fixture(
      name: "wide-and-combining", cols: 80, rows: 24,
      bytes: Array("界e\u{301}z".utf8)),
    Fixture(
      name: "cursor-move-and-query", cols: 80, rows: 24,
      bytes: Array("top\r\n\u{1B}[2;5Hmid\u{1B}[6n\u{1B}[?25l".utf8)),
  ]

  func testCanonicalTextKeepsTrailingSpacesAndOneLineFeedPerRow() throws {
    let session = try XCTUnwrap(TerminalSession(cols: 5, rows: 2))
    session.feed(Array("ab\r\nc".utf8))
    let frame = try XCTUnwrap(session.readFrame())
    session.free()
    XCTAssertEqual(frame.canonicalText(), "ab   \nc    \n")
  }

  func testFirstDifferenceNamesTheByteAndCell() throws {
    let session = try XCTUnwrap(TerminalSession(cols: 4, rows: 1))
    session.feed(Array("abc".utf8))
    let evidence = FrameEvidence(frame: try XCTUnwrap(session.readFrame()))
    session.free()
    XCTAssertNil(evidence.firstDifference(against: evidence, label: "same"))

    var other = evidence
    other.text = "abd \n"
    let textReport = try XCTUnwrap(evidence.firstDifference(against: other, label: "text"))
    XCTAssertTrue(textReport.contains("byte 2, row 0, column 2"), textReport)

    other = evidence
    other.cells[0][0].bold = true
    let cellReport = try XCTUnwrap(evidence.firstDifference(against: other, label: "cell"))
    XCTAssertTrue(cellReport.contains("row 0, column 0"), cellReport)
    XCTAssertTrue(cellReport.contains("bold true"), cellReport)
  }

  func testRawFixtureFramesMatchTheGoOracle() throws {
    let oracle = try OracleRunner.build()
    for fixture in Self.fixtures {
      let session = try XCTUnwrap(TerminalSession(cols: fixture.cols, rows: fixture.rows))
      session.feed(fixture.bytes)
      let frame = try XCTUnwrap(session.readFrame(), fixture.name)
      session.free()

      let directory = FileManager.default.temporaryDirectory
        .appendingPathComponent("phi-oracle-\(UUID().uuidString)")
      try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
      defer { try? FileManager.default.removeItem(at: directory) }
      let oracleFrame = try oracle.decodeRaw(
        fixture.bytes, cols: fixture.cols, rows: fixture.rows)
      let mine = FrameEvidence(frame: frame)
      XCTAssertNil(mine.firstDifference(against: oracleFrame, label: fixture.name))
      XCTAssertEqual(mine.text, oracleFrame.text, fixture.name)
      XCTAssertEqual(mine.cols * mine.rows, oracleFrame.cells.reduce(0) { $0 + $1.count }, fixture.name)
    }
  }

  func testLiveCaptureFilesMatchTheGoOracleWhenCaptured() throws {
    // Set by the probe capture run (`PhiProbe --capture-ansi`): the same state.bin
    // the Swift replay decoded, so the oracle can be compared with it offline.
    guard let directory = ProcessInfo.processInfo.environment["PHI_TEST_CAPTURE_DIR"],
          !directory.isEmpty else {
      throw XCTSkip("PHI_TEST_CAPTURE_DIR is unset; the live capture gate was not run")
    }
    let root = URL(fileURLWithPath: directory)
    let native = try FrameEvidence.decode(
      Data(contentsOf: root.appendingPathComponent("native-frame.json")))
    let live = try FrameEvidence.decode(
      Data(contentsOf: root.appendingPathComponent("live-frame.json")))
    XCTAssertNil(live.firstDifference(against: native, label: "live-vs-replay"))

    let oracleFrame = try OracleRunner.build().decodeCapture(root)
    XCTAssertNil(native.firstDifference(against: oracleFrame, label: "swift-vs-go"))
  }
}
